//! Lenient text handling for XMLTV values.
//!
//! Feeds are generated by many tools and not all of them write valid XML: HTML
//! entities such as `&nbsp;`, bare ampersands and stray line breaks are common.
//! These helpers keep such text instead of rejecting the programme.

use std::borrow::Cow;

/// Longest entity name looked for after `&`. Longer runs are not entities.
const MAX_ENTITY_LEN: usize = 32;

/// HTML entities seen in XMLTV feeds. XML defines only the five predefined
/// ones; the rest are what HTML-minded generators write anyway.
const HTML_ENTITIES: &[(&str, char)] = &[
    ("nbsp", '\u{a0}'),
    ("aacute", 'á'),
    ("Aacute", 'Á'),
    ("agrave", 'à'),
    ("Agrave", 'À'),
    ("acirc", 'â'),
    ("auml", 'ä'),
    ("Auml", 'Ä'),
    ("aring", 'å'),
    ("Aring", 'Å'),
    ("aelig", 'æ'),
    ("AElig", 'Æ'),
    ("ccedil", 'ç'),
    ("Ccedil", 'Ç'),
    ("eacute", 'é'),
    ("Eacute", 'É'),
    ("egrave", 'è'),
    ("Egrave", 'È'),
    ("ecirc", 'ê'),
    ("euml", 'ë'),
    ("iacute", 'í'),
    ("iuml", 'ï'),
    ("ntilde", 'ñ'),
    ("Ntilde", 'Ñ'),
    ("oacute", 'ó'),
    ("Oacute", 'Ó'),
    ("ocirc", 'ô'),
    ("ouml", 'ö'),
    ("Ouml", 'Ö'),
    ("oslash", 'ø'),
    ("Oslash", 'Ø'),
    ("uacute", 'ú'),
    ("uuml", 'ü'),
    ("Uuml", 'Ü'),
    ("szlig", 'ß'),
    ("copy", '©'),
    ("reg", '®'),
    ("trade", '™'),
    ("deg", '°'),
    ("middot", '·'),
    ("hellip", '…'),
    ("ndash", '–'),
    ("mdash", '—'),
    ("lsquo", '‘'),
    ("rsquo", '’'),
    ("ldquo", '“'),
    ("rdquo", '”'),
    ("laquo", '«'),
    ("raquo", '»'),
    ("euro", '€'),
];

/// Whether XML 1.0 allows `c` in a document (its `Char` production): TAB,
/// LF, CR, and everything from U+0020 except U+FFFE and U+FFFF. Surrogates
/// and values past U+10FFFF are not `char`s at all, so `char::from_u32`
/// has already rejected them.
fn is_xml_char(c: char) -> bool {
    matches!(c, '\t' | '\n' | '\r') || (c >= ' ' && c != '\u{fffe}' && c != '\u{ffff}')
}

/// The character an entity name stands for, without the `&` and `;`.
///
/// Covers the five XML entities, decimal (`#49`) and hexadecimal (`#x30`)
/// character references, and a small table of HTML entities. `None` for
/// anything else, including references to code points XML does not allow.
pub fn entity(name: &str) -> Option<char> {
    match name {
        "amp" => return Some('&'),
        "lt" => return Some('<'),
        "gt" => return Some('>'),
        "quot" => return Some('"'),
        "apos" => return Some('\''),
        _ => {}
    }
    if let Some(number) = name.strip_prefix('#') {
        // Digits only: `from_str_radix` and `parse` would also take a sign.
        let code = match number.strip_prefix(['x', 'X']) {
            Some(hex) if !hex.is_empty() && hex.bytes().all(|b| b.is_ascii_hexdigit()) => {
                u32::from_str_radix(hex, 16).ok()?
            }
            None if !number.is_empty() && number.bytes().all(|b| b.is_ascii_digit()) => {
                number.parse::<u32>().ok()?
            }
            _ => return None,
        };
        return char::from_u32(code).filter(|c| is_xml_char(*c));
    }
    HTML_ENTITIES
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, c)| *c)
}

/// Append what an entity reference stands for to `out`, or the reference
/// itself (`&name;`) when the name is unknown, so no text is lost.
pub fn push_reference(out: &mut String, name: &str) {
    match entity(name) {
        Some(c) => out.push(c),
        None => {
            out.push('&');
            out.push_str(name);
            out.push(';');
        }
    }
}

/// Replace entity references in `s` with their characters.
///
/// Unknown references (`&foo;`) and bare ampersands are kept verbatim instead
/// of failing, so one sloppy title does not cost the programme. Borrows when
/// `s` contains no `&`.
pub fn unescape_lenient(s: &str) -> Cow<'_, str> {
    if !s.contains('&') {
        return Cow::Borrowed(s);
    }
    let mut out = String::with_capacity(s.len());
    let mut rest = s;
    while let Some(amp) = rest.find('&') {
        out.push_str(&rest[..amp]);
        let after = &rest[amp + 1..];
        let name_end = after
            .char_indices()
            .take(MAX_ENTITY_LEN + 1)
            .find(|(_, c)| *c == ';' || *c == '&' || c.is_whitespace())
            .filter(|(_, c)| *c == ';')
            .map(|(i, _)| i);
        match name_end.and_then(|end| entity(&after[..end]).map(|c| (end, c))) {
            Some((end, c)) => {
                out.push(c);
                rest = &after[end + 1..];
            }
            None => {
                out.push('&');
                rest = after;
            }
        }
    }
    out.push_str(rest);
    Cow::Owned(out)
}

/// XML's whitespace characters. Other Unicode spaces, the no-break space in
/// particular, are content and stay.
fn is_xml_whitespace(c: char) -> bool {
    matches!(c, ' ' | '\t' | '\n' | '\r')
}

/// Trim `s` and collapse each run of XML whitespace inside it to one space.
///
/// Titles and descriptions arrive indented and wrapped by the generator; the
/// XMLTV DTD leaves that whitespace insignificant. Borrows when nothing changes.
pub fn collapse_whitespace(s: &str) -> Cow<'_, str> {
    let trimmed = s.trim_matches(is_xml_whitespace);
    if !trimmed.contains(['\t', '\n', '\r']) && !trimmed.contains("  ") {
        return Cow::Borrowed(trimmed);
    }
    let mut out = String::with_capacity(trimmed.len());
    for word in trimmed.split(is_xml_whitespace).filter(|w| !w.is_empty()) {
        if !out.is_empty() {
            out.push(' ');
        }
        out.push_str(word);
    }
    Cow::Owned(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_five_xml_entities_are_replaced() {
        assert_eq!(
            unescape_lenient("&amp; &lt; &gt; &quot; &apos;"),
            "& < > \" '"
        );
    }

    #[test]
    fn numeric_references_are_replaced() {
        assert_eq!(unescape_lenient("&#49;&#x30;&#X41;"), "10A");
        assert_eq!(unescape_lenient("M&#229;ndag"), "Måndag");
    }

    #[test]
    fn html_entities_from_the_table_are_replaced() {
        assert_eq!(unescape_lenient("a&nbsp;b"), "a\u{a0}b");
        assert_eq!(unescape_lenient("caf&eacute;"), "café");
    }

    #[test]
    fn unknown_entities_are_kept_verbatim() {
        assert_eq!(unescape_lenient("x &foo; y"), "x &foo; y");
        assert_eq!(unescape_lenient("&#xZZ;"), "&#xZZ;");
        // Surrogates and NUL are not characters XML allows.
        assert_eq!(unescape_lenient("&#xD800;&#0;"), "&#xD800;&#0;");
    }

    #[test]
    fn numeric_references_xml_forbids_are_kept_verbatim() {
        for reference in [
            "&#x110000;",
            "&#1;",
            "&#x1F;",
            "&#xFFFE;",
            "&#xFFFF;",
            "&#99999999999;",
        ] {
            assert_eq!(unescape_lenient(reference), reference);
        }
        // The three control characters XML does allow.
        assert_eq!(unescape_lenient("&#9;&#xA;&#13;"), "\t\n\r");
        assert_eq!(unescape_lenient("&#xFFFD;"), "\u{fffd}");
    }

    #[test]
    fn signed_or_empty_numeric_references_are_kept_verbatim() {
        for reference in ["&#+49;", "&#-49;", "&#x+41;", "&#x-41;", "&#;", "&#x;"] {
            assert_eq!(unescape_lenient(reference), reference);
        }
    }

    #[test]
    fn non_ascii_after_an_ampersand_is_kept() {
        assert_eq!(unescape_lenient("&é"), "&é");
        assert_eq!(unescape_lenient("&é;"), "&é;");
        assert_eq!(unescape_lenient("A&ö B"), "A&ö B");
        assert_eq!(unescape_lenient("A&ö;&amp;"), "A&ö;&");
    }

    #[test]
    fn entity_names_are_looked_for_up_to_32_characters() {
        // "#" plus 31 digits is a 32-character name and still resolves.
        let name_32 = format!("#{:0>31}", 49);
        assert_eq!(unescape_lenient(&format!("&{name_32};")), "1");
        // One digit more and the run is not taken as a reference.
        let name_33 = format!("#{:0>32}", 49);
        let text = format!("&{name_33};");
        assert_eq!(unescape_lenient(&text), text);
    }

    #[test]
    fn bare_ampersands_are_kept() {
        assert_eq!(unescape_lenient("A & E"), "A & E");
        assert_eq!(unescape_lenient("A&E"), "A&E");
        assert_eq!(unescape_lenient("trailing &"), "trailing &");
        assert_eq!(unescape_lenient("&&amp;"), "&&");
        assert_eq!(unescape_lenient("Tom &amp Jerry; x"), "Tom &amp Jerry; x");
    }

    #[test]
    fn text_without_ampersands_is_borrowed() {
        assert!(matches!(unescape_lenient("Rapport"), Cow::Borrowed(_)));
    }

    #[test]
    fn references_are_pushed_or_kept() {
        let mut out = String::new();
        push_reference(&mut out, "amp");
        push_reference(&mut out, "foo");
        push_reference(&mut out, "#x41");
        assert_eq!(out, "&&foo;A");
    }

    #[test]
    fn whitespace_is_trimmed_and_collapsed() {
        assert_eq!(collapse_whitespace("  Tom \n\t  Jerry  "), "Tom Jerry");
        assert_eq!(collapse_whitespace("a\nb"), "a b");
        assert_eq!(collapse_whitespace("\r\n"), "");
    }

    #[test]
    fn no_break_spaces_are_content() {
        assert_eq!(collapse_whitespace(" a\u{a0}\u{a0}b "), "a\u{a0}\u{a0}b");
    }

    #[test]
    fn clean_text_is_borrowed() {
        assert!(matches!(collapse_whitespace("Rapport"), Cow::Borrowed(_)));
        assert!(matches!(collapse_whitespace(" Rapport "), Cow::Borrowed(_)));
        assert!(matches!(collapse_whitespace("a  b"), Cow::Owned(_)));
    }
}
